fn is_ascii_digit(c: char) -> bool {
    // Check if the character is between '0' and '9' inclusive
    c >= '0' && c <= '9'
}

fn all_digits(s: String) -> bool {
    // For empty string, return true (vacuously all characters are digits)
    // For non-empty string, check each character
    s.chars().all(is_ascii_digit)
}